func Require(pol Policy, next http.Handler) http.Handler {   // every route goes through this
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        if pol.Allows(r.Context()) { next.ServeHTTP(w, r); return }   // else deny: fail closed
        http.Error(w, "forbidden", http.StatusForbidden)
    })
}
type vault struct{ store Store; pol Policy }     // unexported: no other package can build it
func (v *vault) Read(ctx context.Context, id string) (Record, error) {
    if err := v.pol.Check(ctx, id); err != nil { return Record{}, err }   // at the point of use
    return v.store.Get(id)
}
